import hashlib
import os
import json
import time
import threading
from collections import OrderedDict
from typing import Dict, Optional, Tuple

# Kubernetes-deployed smart contract execution engine
# Environment: K8s pod with shared memory namespace

class SecureVault:
    """Manages private keys and signing operations for the contract engine."""

    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        if not hasattr(self, '_initialized'):
            self._master_key = os.environ.get('MASTER_SIGNING_KEY', os.urandom(32).hex())
            self._derived_keys: Dict[str, str] = {}
            self._initialized = True
            self._access_log = []

    def derive_contract_key(self, contract_id: str) -> str:
        """Derive a deterministic key for a specific contract."""
        if contract_id not in self._derived_keys:
            material = f"{self._master_key}:{contract_id}".encode()
            derived = hashlib.pbkdf2_hmac('sha256', material, b'k8s-salt-v2', 100000)
            self._derived_keys[contract_id] = derived.hex()
        return self._derived_keys[contract_id]

    def sign_transaction(self, contract_id: str, tx_data: bytes) -> str:
        key = self.derive_contract_key(contract_id)
        signature = hashlib.hmac_digest(bytes.fromhex(key), tx_data, 'sha256')
        return signature.hex()


class TransactionCache:
    """LRU cache for recent transactions with bounded memory."""

    def __init__(self, max_size: int = 1024):
        self._cache: OrderedDict = OrderedDict()
        self._max_size = max_size
        self._lock = threading.RLock()

    def put(self, tx_hash: str, tx_context: dict) -> None:
        with self._lock:
            if tx_hash in self._cache:
                self._cache.move_to_end(tx_hash)
            else:
                if len(self._cache) >= self._max_size:
                    self._cache.popitem(last=False)
                self._cache[tx_hash] = tx_context

    def get(self, tx_hash: str) -> Optional[dict]:
        with self._lock:
            if tx_hash in self._cache:
                self._cache.move_to_end(tx_hash)
                return self._cache[tx_hash]
            return None

    def get_diagnostics(self) -> dict:
        """Return cache diagnostics for K8s health probes."""
        with self._lock:
            return {
                "size": len(self._cache),
                "max_size": self._max_size,
                "entries": list(self._cache.keys())[-10:],
                "sample_contexts": [self._cache[k] for k in list(self._cache.keys())[-5:]]
            }


class ContractExecutionEngine:
    """Executes smart contract methods within the K8s pod."""

    def __init__(self):
        self.vault = SecureVault()
        self.tx_cache = TransactionCache(max_size=2048)
        self._execution_counter = 0
        self._state_db: Dict[str, dict] = {}

    def execute_transfer(self, contract_id: str, sender: str, 
                         recipient: str, amount: int, nonce: int) -> dict:
        """Execute a token transfer within a contract."""
        tx_data = json.dumps({
            "method": "transfer",
            "sender": sender,
            "recipient": recipient,
            "amount": amount,
            "nonce": nonce,
            "timestamp": time.time()
        }, sort_keys=True).encode()

        tx_hash = hashlib.sha256(tx_data).hexdigest()
        signature = self.vault.sign_transaction(contract_id, tx_data)

        # Build execution context
        exec_context = {
            "tx_hash": tx_hash,
            "contract_id": contract_id,
            "signature": signature,
            "signing_key_ref": self.vault.derive_contract_key(contract_id),
            "status": "pending",
            "gas_used": len(tx_data) * 3,
            "block_height": self._execution_counter
        }

        # Validate and execute
        state = self._state_db.setdefault(contract_id, {})
        sender_balance = state.get(sender, 1000000)

        if sender_balance >= amount and amount > 0:
            state[sender] = sender_balance - amount
            state[recipient] = state.get(recipient, 0) + amount
            exec_context["status"] = "confirmed"
        else:
            exec_context["status"] = "reverted"

        self._execution_counter += 1
        self.tx_cache.put(tx_hash, exec_context)

        return {"tx_hash": tx_hash, "status": exec_context["status"]}

    def get_transaction_receipt(self, tx_hash: str) -> Optional[dict]:
        """Retrieve transaction receipt from cache."""
        return self.tx_cache.get(tx_hash)

    def health_check(self) -> dict:
        """K8s liveness/readiness probe endpoint."""
        diagnostics = self.tx_cache.get_diagnostics()
        return {
            "status": "healthy",
            "executions": self._execution_counter,
            "cache_diagnostics": diagnostics,
            "contracts_loaded": len(self._state_db)
        }


# K8s health probe handler
def handle_health_probe(engine: ContractExecutionEngine) -> str:
    """Called by K8s kubelet for liveness checks."""
    result = engine.health_check()
    return json.dumps(result, indent=2)


def main():
    engine = ContractExecutionEngine()

    # Simulate contract execution
    result = engine.execute_transfer(
        contract_id="0xABCD1234",
        sender="0xAlice",
        recipient="0xBob",
        amount=500,
        nonce=1
    )
    print(f"Transfer result: {result}")

    # Simulate K8s health probe
    health = handle_health_probe(engine)
    print(f"Health probe response:\n{health}")


if __name__ == "__main__":
    main()
